// This node groups individual row numbers into consecutive ranges to optimize deletion.
// It receives a list of items, each with a 'row_number'.

const items = $input.all();

// 1. Extract all 'row_number' values from the incoming items.
// Using a Set removes any duplicate row numbers automatically.
// We also filter to ensure we only process actual numbers.
const rowNumbers = [...new Set(items.map(item => item.json.row_number).filter(n => typeof n === 'number'))];

// 2. Sort the unique row numbers in ascending order to make grouping easier.
rowNumbers.sort((a, b) => a - b);

// If there are no valid row numbers, stop execution and return an empty array.
if (rowNumbers.length === 0) {
  return [];
}

const ranges = [];
let startOfRange = rowNumbers[0];
let count = 1;

// 3. Iterate through the sorted numbers to find consecutive blocks.
for (let i = 1; i < rowNumbers.length; i++) {
  // Check if the current number is exactly one greater than the previous one.
  if (rowNumbers[i] === rowNumbers[i - 1] + 1) {
    // It's a consecutive number, so we increment the count for the current range.
    count++;
  } else {
    // The sequence is broken. The previous range has ended, so we save it.
    ranges.push({ startIndex: startOfRange, amount: count });

    // Start a new range with the current number.
    startOfRange = rowNumbers[i];
    count = 1;
  }
}

// 4. After the loop finishes, the very last range needs to be saved.
ranges.push({ startIndex: startOfRange, amount: count });

// 5. CRITICAL STEP: Sort the identified ranges in DESCENDING order of their start index.
// Deleting rows from the bottom of the sheet upwards prevents the row indices
// of subsequent ranges from shifting and causing the wrong rows to be deleted.
ranges.sort((a, b) => b.startIndex - a.startIndex);

// 6. Format the output data structure for n8n. Each range object
// will be processed as a separate item by the next node.
return ranges.map(range => ({ json: range }));

