// ─── Helpers ────────────────────────────────────────────────────────────────

const processedDocs = {
  byId:             new Map(),
  byHash:           new Map(),
  byCompanyShortDoc: new Map(),
};

function isBlank(val) {
  return [null, undefined, '', 'unknown'].includes(
    (String(val ?? '')).toLowerCase()
  );
}

function compositeKey(companyId, shortDocId) {
  return `${companyId}_${shortDocId}`;
}

function checkDuplicate(doc) {
  const id   = doc.ID   ? processedDocs.byId.get(doc.ID)     : undefined;
  const hash = doc.HASH ? processedDocs.byHash.get(doc.HASH) : undefined;
  const comp = (doc.COMPANY_ID && doc.SHORT_DOC_ID)
    ? processedDocs.byCompanyShortDoc.get(compositeKey(doc.COMPANY_ID, doc.SHORT_DOC_ID))
    : undefined;

  const matchedId = id ?? hash ?? comp;
  return {
    idMatch:           id,
    hashMatch:         hash,
    compShortDocMatch: comp,
    match:             matchedId !== undefined,
    matchedId,
  };
}

function trackDoc(doc) {
  const id = String(doc.ID);
  if (doc.ID)                              processedDocs.byId.set(doc.ID, id);
  if (doc.HASH)                            processedDocs.byHash.set(doc.HASH, id);
  if (doc.COMPANY_ID && doc.SHORT_DOC_ID)  
    processedDocs.byCompanyShortDoc.set(compositeKey(doc.COMPANY_ID, doc.SHORT_DOC_ID), id);
}

function resolveDocType(type = '') {
  const t = type.toUpperCase();
  if (['INVOICE', 'SHIPMENT'].includes(t)) return 'gdoc';
  if (t === 'BALANCE_SHEET')               return 'bs_doc';
  return 'unknown';
}

function hasAllRequiredFields(doc, docType) {
  if (docType === 'gdoc') {
    return ['COMPANY_ID', 'COMPANY_DOC_ID', 'SHORT_DOC_ID', 'LINK', 'SHIPMENT_DOC_ID']
      .every(f => doc[f] && doc[f] !== '' && doc[f] !== 'MISSING');
  }
  if (docType === 'bs_doc') {
    return !!(doc.BS_EXTRACTED_LINES &&
              doc.BS_EXTRACTION_VERIFIED === true &&
              doc.BS_LINK_DOCUMENTS_COMPLETED === true);
  }
  return false;
}

// ─── Per-type action routers ─────────────────────────────────────────────────

function gdocAction(doc) {
  if (isBlank(doc.COMPANY_DOC_ID))
    return 'no_action_awating_doc_id';

  if (doc.STATUS === 'ACTION_RESTART')
    return 'restart_gdoc';

  const expectedShort = String(doc.COMPANY_DOC_ID ?? '')
    .trim().replace(/[^a-zA-Z0-9]/g, '').slice(-5).padStart(5, '0');

  if (!doc.SHORT_DOC_ID || String(doc.SHORT_DOC_ID) !== expectedShort)
    return 'get_short_doc_id';

  const expectedName = `${doc.COMPANY_NAME ?? 'unknown'}-${doc.SHORT_DOC_ID ?? 'unknown'}`;
  if (doc.NAME !== expectedName)
    return 'update_name';

  if (['MISSING', '', undefined, null].includes(doc.LINK)) {
    if (!doc.SEARCH_IN_DRIVE_COMPLETED) return 'find_link';
    if (doc.STATUS !== 'MISSING_LINK')  return 'update_status_missing_link';
    return 'no_action_link_not_found';
  }

  if (isBlank(doc.FROM_OFFICE_CHECK))
    return 'check_from_office';

  // Upload to API_TOOLS
  if (isBlank(doc.API_TOOLS_ID) && !doc.API_TOOLS_ID_COMPLETED) {
    return 'get_api_tools_id';
  }
  // if has apitools id -> extract properties via apitools
  if (doc.API_TOOLS_ID) {
    if (!doc.DOC_DATE && !doc.DOC_DATE_COMPLETED)
    return 'query_doc_date';

    if (!doc.DOC_TOTAL_AMOUNT && !doc.DOC_TOTAL_AMOUNT_COMPLETED && doc.TYPE === 'INVOICE')
      return 'query_doc_total_amount';

    if (!doc.PURCHASE_ID && !doc.PURCHASE_ID_COMPLETED)
      return 'query_purchase_id';

    if (!doc.SHIPMENT_DOC_ID && !doc.SHIPMENT_ID_COMPLETED) {
      return 'query_shipment_id';
    }
  }

  if (doc.TYPE=='INVOICE') {
    if (!doc.AI_EXTRACTION_COMPLETED) {
      return 'extract_invoice_google_ai'
    }
    if (!doc.SELECTION_COMPLETED) {
      return 'select_invoice_values'
    }
    if (!doc.PRIORITY_SYNC_COMPLETED) {
      return 'action_priority_sync';
    }
  }



  if (doc.STATUS !== 'COMPLETED') return 'mark_completed';
    return 'no_action_already_completed';
}

function bsDocAction(doc) {
  if (!doc.COMPANY_ID) {
    return doc.STATUS !== 'MISSING_COMPANY_ID'
      ? 'update_status_missing_company'
      : 'no_action_awaiting_company_id';
  }

  if (doc.STATUS === 'ACTION_RESTART')
    return 'restart_balance_sheet';

  if (!doc.BS_EXTRACTED_LINES) {
    if (!doc.BS_EXTRACTED_LINES_COMPLETED)      return 'extract_balance_sheet';
    if (doc.STATUS !== 'EXTRACTION_FAILED')     return 'update_status_extraction_failed';
    return 'no_action_extraction_failed';
  }

  if (!doc.BS_EXTRACTION_VERIFIED)
    return doc.STATUS !== 'EXTRACTION_FAILED'
      ? 'update_status_extraction_failed'
      : 'no_action_extraction_failed';

  if (!doc.BS_LINK_DOCUMENTS_COMPLETED)
    return 'link_documents';

  if (doc.STATUS !== 'COMPLETED' && hasAllRequiredFields(doc, 'bs_doc'))
    return 'mark_completed';

  if (doc.STATUS === 'COMPLETED')
    return 'no_action_already_completed';

  return 'no_action_unhandled_state';
}

function unknownTypeAction(doc) {
  if (!doc.FIGURE_TYPE_COMPLETED || doc.STATUS === 'ACTION_RESTART')
    return 'figure_document_type';
  if (doc.STATUS !== 'MISSING_TYPE')
    return 'update_status_missing_type';
  return 'no_action_unknown_document_type';
}

// ─── Main router ─────────────────────────────────────────────────────────────

function determineAction(doc) {
  // Normalise ID to string upfront so all comparisons are consistent
  const normDoc = { ...doc, ID: doc.ID != null ? String(doc.ID) : doc.ID };

  if (!normDoc.ID) {
    return { json: { ACTION: 'delete_row', DOC_TYPE: 'empty', ...normDoc } };
  }

  const duplicateCheck = checkDuplicate(normDoc);
  if (!duplicateCheck.match) trackDoc(normDoc);

  // Shared guards (apply before type-specific routing)
  let action = null;

  if (duplicateCheck.match) {
    normDoc.DOUBLE_CONTEXT = duplicateCheck;
    action = normDoc.STATUS === 'DOUBLE' ? 'no_action_double' : 'update_status_double';
  } else if (normDoc.STATUS === 'DOUBLE') {
    action = 'no_action_double';
  } else if (normDoc.STATUS === 'PAUSE') {
    action = 'no_action_paused';
  } else if (!normDoc.COMPANY_ID) {
    //  || isNaN(Number(normDoc.COMPANY_ID))
    if (!normDoc.FIGURE_COMPANY_COMPLETED || normDoc.STATUS === 'ACTION_RESTART')
      action = 'figure_company_id';
    else if (normDoc.STATUS !== 'MISSING_COMPANY_ID')
      action = 'update_status_missing_company';
    else
      action = 'no_action_awaiting_company_id';
  } else if (isBlank(normDoc.COMPANY_NAME)) {
    if (!normDoc.COMPANY_NAME_COMPLETED || normDoc.STATUS === 'ACTION_RESTART')
      action = 'get_company_name';
    else
      action = normDoc.STATUS !== 'UNKNOWN_COMPANY'
        ? 'update_status_unknwon_company'
        : 'no_action_awaiting_company_name';
  }

  // Type-specific routing
  if (!action) {
    const docType = resolveDocType(normDoc.TYPE);
    const typeAction =
      docType === 'gdoc'    ? gdocAction(normDoc) :
      docType === 'bs_doc'  ? bsDocAction(normDoc) :
                              unknownTypeAction(normDoc);

    return { json: { ACTION: typeAction, DOC_TYPE: docType, ...normDoc } };
  }

  const docType = resolveDocType(normDoc.TYPE);
  return { json: { ACTION: action, DOC_TYPE: docType, ...normDoc } };
}

// ─── Entry point ─────────────────────────────────────────────────────────────

return $input.all().map(x => determineAction(x.json));

// ─── Assertion node (runs after determineAction) ──────────────────────────
return $input.all().map(item => {
  const expected = item.json.expected_action;
  const actual   = item.json.ACTION;
  const pass     = actual === expected;

  return {
    json: {
      pass,
      result: pass ? '✓ PASS' : `✗ FAIL — expected: ${expected}, got: ${actual}`,
      ...item.json,


    }
  };
});

