// Helper function to check if document has all required fields
function hasAllRequiredFields(doc, type) {
  if (type === 'gdoc') {
    const requiredFields = [
      'COMPANY_ID',
      'COMPANY_DOC_ID', 
      'SHORT_DOC_ID',
      'LINK',
      "SHIPMENT_DOC_ID"
    ];

    return requiredFields.every(field => 
      doc[field] && doc[field] !== '' && doc[field] !== 'MISSING' && doc[field] !== null && doc[field] !== undefined
    );
  } else if (type === 'bs_doc') {
    return doc.BS_EXTRACTED_LINES && 
           doc.BS_EXTRACTION_VERIFIED === true &&
           doc.BS_LINK_DOCUMENTS_COMPLETED === true;
  }
  return false;
}

