function getCompositeKey(companyId, shortDocId) {
  return `${companyId}_${shortDocId}`;
}

/**
 * Checks if a document has already been processed
 * @returns {Object} Match details and matched index
 */
function checkDuplicate(doc) {
  const result = {
    idMatch: false,
    hashMatch: false,
    compShortDocMatch: false,
    match: false,
    matchedId: null
  };

  // Check ID match
  if (doc.ID && processedDocs.byId.has(doc.ID)) {
    result.idMatch = processedDocs.byId.get(doc.ID);
    result.match = true;
    result.matchedId = result.idMatch;
  }

  // Check hash match
  if (doc.HASH && processedDocs.byHash.has(doc.HASH)) {
    result.hashMatch = processedDocs.byHash.get(doc.HASH);
    result.match = true;
    result.matchedId = result.matchedId ?? result.hashMatch;
  }

  // Check composite key match
  if (doc.COMPANY_ID && doc.SHORT_DOC_ID) {
    const compositeKey = getCompositeKey(doc.COMPANY_ID, doc.SHORT_DOC_ID);
    if (processedDocs.byCompanyShortDoc.has(compositeKey)) {
      result.compShortDocMatch = processedDocs.byCompanyShortDoc.get(compositeKey);
      result.match = true;
      result.matchedId = result.matchedId ?? result.compShortDocMatch;
    }
  }

  return result;
}

/**
 * Adds a document to the processed tracking
 */
function addProcessedDoc(doc, id) {
  if (doc.ID) {
    processedDocs.byId.set(doc.ID, id);
  }
  if (doc.HASH) {
    processedDocs.byHash.set(doc.HASH, id);
  }
  if (doc.COMPANY_ID && doc.SHORT_DOC_ID) {
    console.log("add p doc", doc.COMPANY_ID, doc.SHORT_DOC_ID)
    const compositeKey = getCompositeKey(doc.COMPANY_ID, doc.SHORT_DOC_ID);
    processedDocs.byCompanyShortDoc.set(compositeKey, id);
  }
}



