  });

  const aiBsMatch = 
    has(dimensions.date.AI) && has(dimensions.date.BS) && dimensions.date.AI === dimensions.date.BS &&
    has(dimensions.amount.AI) && has(dimensions.amount.BS) && dimensions.amount.AI === dimensions.amount.BS;

  let finalScore = 0;
