  item.json.SELECTED_DOC_AMOUNT = dimensions.amount.AI || dimensions.amount.BS || dimensions.amount.KW;
  item.json.SELECTED_DOC_DATE   = dimensions.date.AI || dimensions.date.BS || dimensions.date.KW;

  item.json.SELECTION_CERTAINTY = finalScore;
  item.json.SELECTION_COMPLETED = finalScore > 0;
  item.json.SELECTION_SOURCE    = idMismatch ? "ID_MISMATCH" : (aiBsMatch ? "AI+BS" : "OTHER");
  item.json.SELECTION_SCORE_DEBUG = report;
}

